	@Test
	public void testGroupIteratorClose() throws QueryEvaluationException, InterruptedException {
		// Lock which is already locked to block the thread driving the iteration
		Lock lock = new ReentrantLock();
		lock.lock();
		// Latch to rendezvous on with the iterating thread
		CountDownLatch iterating = new CountDownLatch(1);
		// Latch to record whether the iteration under GroupIterator was closed
		CountDownLatch closed = new CountDownLatch(1);

		EvaluationStrategy evaluator = new DefaultEvaluationStrategy(null, null) {
			@Override
			protected QueryEvaluationStep prepare(EmptySet emptySet, QueryEvaluationContext context)
					throws QueryEvaluationException {
				return bindings -> new LookAheadIteration<>() {
					@Override
					protected BindingSet getNextElement() {
						iterating.countDown(); // signal to test thread iteration started
						lock.lock(); // block iterating thread
						return null;
					}

					@Override
					protected void handleClose() {
						closed.countDown();
					}
				};
			}
		};

		Group group = new Group(new EmptySet());
		GroupIterator groupIterator = new GroupIterator(evaluator, group, EmptyBindingSet.getInstance(), CONTEXT);

		Thread iteratorThread = new Thread(groupIterator::next, "GroupIteratorTest#testGroupIteratorClose");
		try {
			iteratorThread.start();
			assertThat(iterating.await(5, TimeUnit.SECONDS)).isTrue();
			groupIterator.close();
			assertThat(closed.await(5, TimeUnit.SECONDS)).isTrue();
		} finally {
			lock.unlock();
			iteratorThread.join(Duration.ofSeconds(5).toMillis());
			assertThat(iteratorThread.isAlive()).isFalse();
		}
	}

	@Test
	public void testCircuitBreakerInterruptsGroupIterator() throws Exception {
		Group group = new Group(NONEMPTY_ASSIGNMENT);
		group.addGroupBindingName("a");

		QueryCircuitBreaker breaker = QueryCircuitBreaker.getInstance();
		withCriticalBreakerProperties(() -> {
			QueryCircuitBreakerHandle handle = breaker.register(QueryCircuitBreakerHandle.Source.WORKBENCH, "test",
					"select * where { ?s ?p ?o } group by ?a");
			try (QueryExecutionContext.Activation ignored = QueryExecutionContext.activate(handle);
					GroupIterator groupIterator = new GroupIterator(EVALUATOR, group, EmptyBindingSet.getInstance(),
							CONTEXT)) {
				assertThatExceptionOfType(QueryInterruptedException.class).isThrownBy(groupIterator::next);
			} finally {
				breaker.complete(handle);
			}
		});
	}

	private void withCriticalBreakerProperties(ThrowingRunnable action) throws Exception {
		String previousEnabled = System.getProperty(BREAKER_ENABLED);
		String previousWarnFreeMb = System.getProperty(BREAKER_WARN_FREE_MB);
		String previousHighFreeMb = System.getProperty(BREAKER_HIGH_FREE_MB);
		String previousCriticalFreeMb = System.getProperty(BREAKER_CRITICAL_FREE_MB);
		try {
			resetGlobalBreaker();
			System.setProperty(BREAKER_ENABLED, "true");
			System.setProperty(BREAKER_WARN_FREE_MB, Integer.toString(Integer.MAX_VALUE));
			System.setProperty(BREAKER_HIGH_FREE_MB, Integer.toString(Integer.MAX_VALUE));
			System.setProperty(BREAKER_CRITICAL_FREE_MB, Integer.toString(Integer.MAX_VALUE));
			action.run();
		} finally {
			restoreProperty(BREAKER_ENABLED, previousEnabled);
			restoreProperty(BREAKER_WARN_FREE_MB, previousWarnFreeMb);
			restoreProperty(BREAKER_HIGH_FREE_MB, previousHighFreeMb);
			restoreProperty(BREAKER_CRITICAL_FREE_MB, previousCriticalFreeMb);
			resetGlobalBreaker();
		}
	}

	@Test
	public void testHeavyOperatorKillSwitchInterruptsGroupIteratorWithoutBreakerCheckpoint() throws Exception {
		Group group = new Group(NONEMPTY_ASSIGNMENT);
		group.addGroupBindingName("a");
		QueryCircuitBreaker breaker = QueryCircuitBreaker.getInstance();
		withCriticalBreakerProperties(() -> {
			// Register after reset and establish the real policy, rather than overwriting a monitor-owned flag.
			QueryCircuitBreakerHandle handle = breaker.register(QueryCircuitBreakerHandle.Source.WORKBENCH, "test",
					"select * where { ?s ?p ?o } group by ?a");
			try (QueryExecutionContext.Activation ignored = QueryExecutionContext.activate(handle);
					GroupIterator groupIterator = new GroupIterator(EVALUATOR, group, EmptyBindingSet.getInstance(),
							CONTEXT)) {
				// The same refresh that invalidated the old reflected flag now preserves the actual kill policy.
				assertThat(breaker.snapshotStatus().getState()).isEqualTo("CRITICAL");
				assertThatExceptionOfType(QueryInterruptedException.class).isThrownBy(groupIterator::next);
				assertThat(handle.isCancelRequested()).isTrue();
				assertThat(handle.getLastHeavyOperator())
						.as("the direct kill guard must interrupt before a GROUP_BY_START or GROUP_BY_BUILD checkpoint")
						.isEqualTo("GROUP_BY");
			} finally {
				breaker.complete(handle);
			}
		});
	}

	private void resetGlobalBreaker() throws Exception {
		QueryCircuitBreaker breaker = QueryCircuitBreaker.getInstance();
		Field activeHandlesField = QueryCircuitBreaker.class.getDeclaredField("activeHandles");
		activeHandlesField.setAccessible(true);
		((Map<?, ?>) activeHandlesField.get(breaker)).clear();
		resetCounter(breaker, "handleSequence");
		resetCounter(breaker, "rejectCount");
		resetCounter(breaker, "cancelCount");

		Field currentStateField = QueryCircuitBreaker.class.getDeclaredField("currentState");
		currentStateField.setAccessible(true);
		currentStateField.set(breaker, QueryPressureState.NORMAL);

		Field lastCancelAtField = QueryCircuitBreaker.class.getDeclaredField("lastCancelAt");
		lastCancelAtField.setAccessible(true);
		lastCancelAtField.setLong(breaker, Long.MIN_VALUE);

		Class<?> transitionClass = Class.forName("org.eclipse.rdf4j.http.client.QueryCircuitBreaker$Transition");
		Method initialMethod = transitionClass.getDeclaredMethod("initial");
		initialMethod.setAccessible(true);
		Object initialTransition = initialMethod.invoke(null);

		Field lastTransitionField = QueryCircuitBreaker.class.getDeclaredField("lastTransition");
		lastTransitionField.setAccessible(true);
		lastTransitionField.set(breaker, initialTransition);
	}

	private void resetCounter(QueryCircuitBreaker breaker, String fieldName) throws Exception {
		Field field = QueryCircuitBreaker.class.getDeclaredField(fieldName);
		field.setAccessible(true);
		((AtomicLong) field.get(breaker)).set(0);
	}

	private void restoreProperty(String propertyName, String value) {
		if (value == null) {
			System.clearProperty(propertyName);
		} else {
			System.setProperty(propertyName, value);
		}
	}

	@FunctionalInterface
	private interface ThrowingRunnable {
		void run() throws Exception;
	}

	private static final class FakeAggregateFunctionFactory implements AggregateFunctionFactory {
		@Override
		public String getIri() {
			return "https://www.rdf4j.org/aggregate#x";
		}

		@Override
		public AggregateFunction<SumCollector, Value> buildFunction(Function<BindingSet, Value> evaluationStep) {
			return new AggregateFunction<>(evaluationStep) {

				private ValueExprEvaluationException typeError = null;

				@Override
				public void processAggregate(BindingSet s, Predicate<Value> distinctValue, SumCollector sum)
						throws QueryEvaluationException {
					if (typeError != null) {
						// halt further processing if a type error has been raised
						return;
					}
					Value v = evaluate(s);
					if (v instanceof Literal nextLiteral) {
						if (distinctValue.test(v)) {
							if (nextLiteral.getDatatype() != null
									&& XMLDatatypeUtil.isNumericDatatype(nextLiteral.getDatatype())) {
								sum.value = MathUtil.compute(sum.value, nextLiteral, MathExpr.MathOp.PLUS);
							} else {
								typeError = new ValueExprEvaluationException("not a number: " + v);
							}
						} else {
							typeError = new ValueExprEvaluationException("not a number: " + v);
						}
					}
				}
			};
		}

		@Override
		public SumCollector getCollector() {
			return new SumCollector();
		}
	}

	private static final class CountingAggregateFunctionFactory implements AggregateFunctionFactory {
		private static final String IRI = "https://www.rdf4j.org/aggregate#invocationCount";
		private final AtomicInteger calls = new AtomicInteger();

		@Override
		public String getIri() {
			return IRI;
		}

		@Override
		public AggregateFunction<InvocationCollector, Value> buildFunction(
				Function<BindingSet, Value> evaluationStep) {
			return new AggregateFunction<>(evaluationStep) {
				@Override
				public void processAggregate(BindingSet bindingSet, Predicate<Value> distinctValue,
						InvocationCollector collector) {
					calls.incrementAndGet();
				}
			};
		}

		@Override
		public InvocationCollector getCollector() {
			return new InvocationCollector();
		}
	}

	private static final class InvocationCollector implements AggregateCollector {
		@Override
		public Value getFinalValue() {
			return VF.createLiteral(0);
		}
	}

	private static final class FakeAggregateNAryFunctionFactory implements AggregateNAryFunctionFactory {
		@Override
		public String getIri() {
			return "https://www.rdf4j.org/aggregate#nary";
		}

		@Override
		public AggregateNAryFunction<SumCollector, Value> buildFunction(
				BiFunction<Integer, BindingSet, Value> evaluationStepByIndex) {
			return new AggregateNAryFunction<>(evaluationStepByIndex) {
				private ValueExprEvaluationException typeError = null;

				@Override
				public void processAggregate(BindingSet bindingSet, Predicate<List<Value>> distinctValue,
						SumCollector sum)
						throws QueryEvaluationException {
					if (typeError != null) {
						// halt further processing if a type error has been raised
						return;
					}
					Value v = evaluate(0, bindingSet); // take first argument as binding set
					Value v2 = evaluate(1, bindingSet); // take second argument as binding set

					if (v instanceof Literal nextLiteral) {
						if (distinctValue.test(List.of(v))) {
							if (nextLiteral.getDatatype() != null
									&& XMLDatatypeUtil.isNumericDatatype(nextLiteral.getDatatype())) {
								sum.value = MathUtil.compute(sum.value, nextLiteral, MathExpr.MathOp.PLUS);
							} else {
								typeError = new ValueExprEvaluationException("not a number: " + v);
							}
						} else {
							typeError = new ValueExprEvaluationException("not a number: " + v);
						}
					}

					if (v2 instanceof Literal nextLiteral) {
						if (distinctValue.test(List.of(v2))) {
							if (nextLiteral.getDatatype() != null
									&& XMLDatatypeUtil.isNumericDatatype(nextLiteral.getDatatype())) {
								sum.value = MathUtil.compute(sum.value, nextLiteral, MathExpr.MathOp.PLUS);
							} else {
								typeError = new ValueExprEvaluationException("not a number: " + v2);
							}
						} else {
							typeError = new ValueExprEvaluationException("not a number: " + v2);
						}
					}
				}
			};
		}

		@Override
		public SumCollector getCollector() {
			return new SumCollector();
		}
	}

	private static final class DistinctTupleTouchingAggregateNAryFunctionFactory
			implements AggregateNAryFunctionFactory {
		@Override
		public String getIri() {
			return "https://www.rdf4j.org/aggregate#nary-distinct-touching";
		}

		@Override
		public AggregateNAryFunction<SumCollector, Value> buildFunction(
				BiFunction<Integer, BindingSet, Value> evaluationStepByIndex) {
			return new AggregateNAryFunction<>(evaluationStepByIndex) {

				@Override
				public void processAggregate(BindingSet bindingSet, Predicate<List<Value>> distinctValue,
						SumCollector sumCollector) throws QueryEvaluationException {
					List<Value> tuple = new ArrayList<>(2);
					tuple.add(evaluate(0, bindingSet));
					tuple.add(evaluate(1, bindingSet));
					distinctValue.test(tuple);
				}
			};
		}

		@Override
		public SumCollector getCollector() {
			return new SumCollector();
		}
	}

